int create_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct user_surface *surface;
    int ret;

    if (!dev || !data || !file_priv) {
        return -EINVAL;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        return -ENOMEM;
    }

    mutex_lock(&dev->mode_config.mutex);
    ret = allocate_buffer(dev, surface, data);
    if (ret) {
        goto error_unlock;
    }

    ret = initialize_surface(surface, data, file_priv);
    if (ret) {
        goto error_free_buffer;
    }

    prepare_surface_response(data, surface);

    mutex_unlock(&dev->mode_config.mutex);
    return 0;

error_free_buffer:
    free_buffer(surface);
error_unlock:
    mutex_unlock(&dev->mode_config.mutex);
    kfree(surface);
    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj = NULL;
    struct drm_plane *plane = NULL;

    if (!dev || !file_priv || !data)
        return -EINVAL;

    memcpy(&args, data, sizeof(args));

    obj = drm_gem_cma_create(dev, args.width * args.height * 4);
    if (!obj)
        return -ENOMEM;

    plane = kzalloc(sizeof(*plane), GFP_KERNEL);
    if (!plane) {
        ret = -ENOMEM;
        goto free_obj;
    }

    plane->fb = drm_framebuffer_alloc(dev, &drm_cma_fb_funcs, args.width, args.height);
    if (!plane->fb) {
        ret = -ENOMEM;
        goto free_plane;
    }

    plane->fb->obj[0] = obj;

    ret = drm_mode_addFB(dev, plane->fb, &plane->fb->width, &plane->fb->height, 32, 0, 0, 0, 0, 0);
    if (ret) {
        DRM_ERROR("Failed to add FB: %d\n", ret);
        goto free_fb;
    }

    ret = 0;
    return ret;

free_fb:
    drm_framebuffer_put(plane->fb);
free_plane:
    kfree(plane);
free_obj:
    drm_gem_object_put(obj);
    return ret;
}

int create_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct user_surface *surface = NULL;

    if (!dev || !data || !file_priv) {
        goto out;
    }

    surface = kzalloc(sizeof(*surface), GFP_KERNEL);
    if (!surface) {
        ret = -ENOMEM;
        goto out;
    }

    mutex_lock(&dev->mode_config.mutex);

    /* Initialize the surface and manage resources here */
    ret = allocate_and_init_surface(surface, data, file_priv);
    if (ret < 0) {
        goto unlock_and_free;
    }

    ret = manage_surface_resources(surface);
    if (ret < 0) {
        goto unlock_and_free;
    }

    /* Prepare the response structure with surface details */
    prepare_response_structure(surface, data);

    mutex_unlock(&dev->mode_config.mutex);

    return 0;

unlock_and_free:
    mutex_unlock(&dev->mode_config.mutex);
    kfree(surface);
out:
    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj;
    struct drm_plane *plane;
    struct drm_framebuffer *fb;

    if (!dev || !data || !file_priv)
        return -EINVAL;

    memcpy(&args, data, sizeof(args));

    ret = drm_mode_dumb_get_info(dev, file_priv, &args);
    if (ret)
        return ret;

    obj = drm_gem_object_create(dev, args.size);
    if (IS_ERR(obj))
        return PTR_ERR(obj);

    fb = drm_framebuffer_alloc(dev, 1, file_priv);
    if (!fb) {
        ret = -ENOMEM;
        goto err_put_gem;
    }

    ret = drm_framebuffer_init(dev, fb, &drm_simple_framebuffer_funcs);
    if (ret)
        goto err_free_fb;

    ret = drm_framebuffer_add(fb);
    if (ret)
        goto err_uninit_fb;

    plane = drm_plane_create(dev, DRM_PLANE_TYPE_PRIMARY, NULL, NULL, NULL, DRM_MODE_BLEND_PREMULTIPLIED);
    if (!plane) {
        ret = -ENOMEM;
        goto err_uninit_fb;
    }

    ret = drm_mode_dumb_add(dev, file_priv, obj, &args);
    if (ret)
        goto err_cleanup_plane;

    return 0;

err_cleanup_plane:
    drm_plane_cleanup(plane);
err_uninit_fb:
    drm_framebuffer_cleanup(fb);
err_free_fb:
    drm_framebuffer_free(fb);
err_put_gem:
    drm_gem_object_put(obj);

    return ret;
}

int create_graphics_buffer_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    int ret = -EINVAL;
    struct drm_mode_create_dumb args;
    struct drm_gem_object *obj = NULL;
    struct drm_plane *plane = NULL;

    if (!dev || !file_priv || !data) {
        return -EINVAL;
    }

    memcpy(&args, data, sizeof(args));

    obj = drm_gem_object_create(dev, args.size);
    if (IS_ERR(obj)) {
        return PTR_ERR(obj);
    }

    plane = drm_plane_create(dev, DRM_PLANE_TYPE_PRIMARY, 0, NULL, NULL, NULL, NULL);
    if (!plane) {
        ret = -ENOMEM;
        goto fail_gem_object;
    }

    ret = drm_plane_attach_plane(plane, NULL);
    if (ret) {
        goto fail_plane;
    }

    args.handle = obj->handle;
    args.pitch = args.width * 4; /* Assuming 4 bytes per pixel for ARGB */
    args.size = args.pitch * args.height;

    memcpy(data, &args, sizeof(args));

    return 0;

fail_plane:
    drm_plane_cleanup(plane);
fail_gem_object:
    drm_gem_object_put(obj);
    return ret;
}
